);

CREATE TABLE helper_repliers (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  batchid bigint NOT NULL,
  userid bigint NOT NULL,
  chatid bigint,
  state text DEFAULT 'NEW' NOT NULL,
  collection_ok text DEFAULT 'unknown' NOT NULL,
  criteria_met text DEFAULT 'unknown' NOT NULL,
  transport_ok text DEFAULT 'unknown' NOT NULL,
  distance_miles numeric(7,2),
  is_connector smallint DEFAULT 0 NOT NULL,
  related_to bigint,
  escalation_reason varchar(512),
  parked_reason varchar(512),
  next_action varchar(512),
  other_items_mentioned smallint DEFAULT 0 NOT NULL,
  cooldown_until timestamptz,
  offerer_last_message_at timestamptz,
  last_processed_chatmsgid bigint,
  knowledge jsonb,
  created_at timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  updated_at timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  CONSTRAINT helper_repliers_state_check CHECK (state IN ('NEW', 'GATHERING', 'QUALIFIED', 'ALLOCATED', 'CONFIRMED', 'COLLECTED', 'PARKED_REPLIED', 'PARKED_QUIET', 'ESCALATED', 'TIMED_OUT', 'WITHDRAWN', 'REJECTED')),
  CONSTRAINT helper_repliers_collection_ok_check CHECK (collection_ok IN ('yes', 'no', 'unknown')),
  CONSTRAINT helper_repliers_criteria_met_check CHECK (criteria_met IN ('yes', 'no', 'unknown', 'na')),
  CONSTRAINT helper_repliers_transport_ok_check CHECK (transport_ok IN ('yes', 'no', 'unknown')),
  PRIMARY KEY (id)
);

CREATE TABLE helper_sent_messages (
