CREATE TABLE logs (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  timestamp timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  byuser bigint,
  type text,
  subtype text,
  groupid bigint,
  "user" bigint,
  msgid bigint,
  configid bigint,
  stdmsgid bigint,
  bulkopid bigint,
  text text,
  CONSTRAINT logs_type_check CHECK (type IN ('Group', 'Message', 'User', 'Plugin', 'Config', 'StdMsg', 'Location', 'BulkOp', 'Chat')),
  CONSTRAINT logs_subtype_check CHECK (subtype IN ('Created', 'Deleted', 'Received', 'Sent', 'Failure', 'ClassifiedSpam', 'Joined', 'Left', 'Approved', 'Rejected', 'YahooDeliveryType', 'YahooPostingStatus', 'NotSpam', 'Login', 'Hold', 'Release', 'Edit', 'RoleChange', 'Merged', 'Split', 'Replied', 'Mailed', 'Applied', 'Suspect', 'Licensed', 'LicensePurchase', 'YahooApplied', 'YahooConfirmed', 'YahooJoined', 'MailOff', 'EventsOff', 'NewslettersOff', 'RelevantOff', 'Logout', 'Bounce', 'SuspendMail', 'Autoreposted', 'Outcome', 'OurPostingStatus', 'VolunteersOff', 'Autoapproved', 'Unbounce', 'WorryWords', 'NoteAdded', 'PostcodeChange', 'Repost', 'OurEmailFrequency', 'Restored')),
  PRIMARY KEY (id)
);

CREATE TABLE logs_emails (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  timestamp timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  eximid varchar(12),
