  userid bigint,
  text text NOT NULL,
  CONSTRAINT logs_errors_type_check CHECK (type IN ('Exception')),
  PRIMARY KEY (id)
);

CREATE TABLE logs_events (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  userid bigint,
  sessionid varchar(32),
