  domain citext NOT NULL,
  waiting bigint DEFAULT 0 NOT NULL,
  deferred bigint DEFAULT 0 NOT NULL,
  oldest timestamptz,
  deliveredperhour bigint DEFAULT 0 NOT NULL,
  instance varchar(255),
  scanned timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  CONSTRAINT mail_relay_queue_domain_length CHECK (char_length(domain) <= 255),
  PRIMARY KEY (id)
);

CREATE TABLE mail_suppressed_counts (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  userid bigint NOT NULL,
  emailtype varchar(32) NOT NULL,
  suppressionid bigint,
  count bigint DEFAULT 0 NOT NULL,
  firstat timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  lastat timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  caughtup_at timestamptz,
  created timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  modified timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  lastkey bigint,
  PRIMARY KEY (id)
);

CREATE TABLE mail_suppressions (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  scope text NOT NULL,
  value citext NOT NULL,
  parentid bigint,
  reason text,
  provider varchar(64),
  deferred_since timestamptz,
  first_seen timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  last_seen timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  released_at timestamptz,
  message_count bigint DEFAULT 0 NOT NULL,
  clear_scans smallint DEFAULT 0 NOT NULL,
  created timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  modified timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  active_value citext GENERATED ALWAYS AS ((CASE WHEN (released_at is null) THEN value ELSE NULL END)) STORED,
  CONSTRAINT mail_suppressions_scope_check CHECK (scope IN ('mxgroup', 'domain', 'address')),
  CONSTRAINT mail_suppressions_value_length CHECK (char_length(value) <= 255),
  CONSTRAINT mail_suppressions_active_value_length CHECK (char_length(active_value) <= 255),
  PRIMARY KEY (id)
);

CREATE TABLE memberships (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  userid bigint NOT NULL,
  groupid bigint NOT NULL,
  role text DEFAULT 'Member' NOT NULL,
  collection text DEFAULT 'Approved' NOT NULL,
  configid bigint,
  added timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  settings text,
  syncdelete smallint DEFAULT 0 NOT NULL,
  heldby bigint,
  emailfrequency integer DEFAULT 24 NOT NULL,
  eventsallowed smallint DEFAULT 1,
  volunteeringallowed bigint DEFAULT 1 NOT NULL,
  rippled smallint DEFAULT 0 NOT NULL,
  implicit smallint DEFAULT 0 NOT NULL,
  added_origin text DEFAULT 'unknown' NOT NULL,
  "ourPostingStatus" text,
  reviewrequestedat timestamptz,
  reviewreason varchar(255),
  reviewedat timestamptz,
  CONSTRAINT memberships_role_check CHECK (role IN ('Member', 'Moderator', 'Owner')),
  CONSTRAINT memberships_collection_check CHECK (collection IN ('Approved', 'Pending', 'Banned')),
  CONSTRAINT memberships_added_origin_check CHECK (added_origin IN ('manual', 'posted', 'replied', 'subscribed', 'rippled', 'moderator', 'partner', 'tn_unaddressed', 'signup', 'unknown')),
  CONSTRAINT "memberships_ourPostingStatus_check" CHECK ("ourPostingStatus" IN ('MODERATED', 'DEFAULT', 'PROHIBITED', 'UNMODERATED')),
  PRIMARY KEY (id)
);

CREATE TABLE memberships_history (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  userid bigint NOT NULL,
  groupid bigint NOT NULL,
  collection text NOT NULL,
  added timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  processingrequired smallint DEFAULT 0 NOT NULL,
  rippled smallint DEFAULT 0 NOT NULL,
  added_origin text DEFAULT 'unknown' NOT NULL,
  CONSTRAINT memberships_history_collection_check CHECK (collection IN ('Approved', 'Pending', 'Banned')),
  CONSTRAINT memberships_history_added_origin_check CHECK (added_origin IN ('manual', 'posted', 'replied', 'subscribed', 'rippled', 'moderator', 'partner', 'tn_unaddressed', 'signup', 'unknown')),
  PRIMARY KEY (id)
);

CREATE TABLE memberships_yahoo (
