  yahooapprove varchar(255),
  yahooreject varchar(255),
  joincomment varchar(255),
  CONSTRAINT memberships_yahoo_role_check CHECK (role IN ('Member', 'Moderator', 'Owner')),
  CONSTRAINT memberships_yahoo_collection_check CHECK (collection IN ('Approved', 'Pending', 'Banned')),
  CONSTRAINT "memberships_yahoo_yahooPostingStatus_check" CHECK ("yahooPostingStatus" IN ('MODERATED', 'DEFAULT', 'PROHIBITED', 'UNMODERATED')),
  CONSTRAINT "memberships_yahoo_yahooDeliveryType_check" CHECK ("yahooDeliveryType" IN ('DIGEST', 'NONE', 'SINGLE', 'ANNOUNCEMENT')),
  PRIMARY KEY (id)
);

CREATE TABLE memberships_yahoo_dump (
