);

CREATE TABLE messages (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  arrival timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  date timestamptz,
  deleted timestamptz,
  heldby bigint,
  source text,
  sourceheader varchar(80),
  fromip varchar(40),
  fromcountry varchar(2),
  message text NOT NULL,
  fromuser bigint,
  envelopefrom varchar(255),
  fromname varchar(255),
  fromaddr varchar(255),
  envelopeto varchar(255),
  replyto varchar(255),
  subject varchar(255),
  suggestedsubject varchar(255),
  type text,
  messageid citext,
  tnpostid varchar(80),
  textbody text,
  htmlbody text,
  retrycount integer DEFAULT 0 NOT NULL,
  retrylastfailure timestamptz,
  spamtype text,
  spamreason varchar(255),
  lat numeric(10,6),
  lng numeric(10,6),
  locationid bigint,
  editedby bigint,
  editedat timestamptz,
  availableinitially integer DEFAULT 1 NOT NULL,
  availablenow integer DEFAULT 1 NOT NULL,
  lastroute varchar(20),
  deliverypossible smallint DEFAULT 0 NOT NULL,
  deadline date,
  CONSTRAINT messages_source_check CHECK (source IN ('Yahoo Approved', 'Yahoo Pending', 'Yahoo System', 'Platform', 'Email')),
  CONSTRAINT messages_type_check CHECK (type IN ('Offer', 'Taken', 'Wanted', 'Received', 'Admin', 'Other')),
  CONSTRAINT messages_messageid_length CHECK (char_length(messageid) <= 255),
  CONSTRAINT messages_spamtype_check CHECK (spamtype IN ('CountryBlocked', 'IPUsedForDifferentUsers', 'IPUsedForDifferentGroups', 'SubjectUsedForDifferentGroups', 'SpamAssassin', 'NotSpam', 'WorryWord', 'Greetings spam', 'Referenced known spammer', 'Known spam keyword', 'URL on DBL', 'BulkVolunteerMail', 'UsedOurDomain')),
  PRIMARY KEY (id)
);

