  item2 bigint,
  facebook_post bigint,
  rotatedimage bigint,
  score_positive numeric(10,4) DEFAULT 0.0000 NOT NULL,
  score_negative numeric(10,4) NOT NULL,
  modfeedback text,
  aiimageid bigint,
  containspeople smallint,
  eee_attachment_id bigint,
