  CONSTRAINT microactions_msgcategory_check CHECK (msgcategory IN ('CouldBeBetter', 'ShouldntBeHere', 'NotSure')),
  CONSTRAINT microactions_result_check CHECK (result IN ('Approve', 'Reject', 'Suppress')),
