  PRIMARY KEY (id)
);

CREATE TABLE mod_configs (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  name varchar(255) NOT NULL,
  createdby bigint,
  fromname text DEFAULT 'My name' NOT NULL,
  ccrejectto text DEFAULT 'Nobody' NOT NULL,
  ccrejectaddr varchar(255) NOT NULL,
  ccfollowupto text DEFAULT 'Nobody' NOT NULL,
  ccfollowupaddr varchar(255) NOT NULL,
  ccrejmembto text DEFAULT 'Nobody' NOT NULL,
  ccrejmembaddr varchar(255) NOT NULL,
  ccfollmembto text DEFAULT 'Nobody' NOT NULL,
  ccfollmembaddr varchar(255) NOT NULL,
  protected smallint DEFAULT 0 NOT NULL,
  messageorder text,
  network varchar(255) NOT NULL,
  coloursubj smallint DEFAULT 1 NOT NULL,
  subjreg varchar(1024) DEFAULT '^(OFFER|WANTED|TAKEN|RECEIVED) *[\:-].*\(.*\)' NOT NULL,
  subjlen integer DEFAULT 68 NOT NULL,
  "default" smallint DEFAULT 0 NOT NULL,
  chatread smallint DEFAULT 0 NOT NULL,
  CONSTRAINT mod_configs_fromname_check CHECK (fromname IN ('My name', 'Groupname Moderator')),
  CONSTRAINT mod_configs_ccrejectto_check CHECK (ccrejectto IN ('Nobody', 'Me', 'Specific')),
  CONSTRAINT mod_configs_ccfollowupto_check CHECK (ccfollowupto IN ('Nobody', 'Me', 'Specific')),
  CONSTRAINT mod_configs_ccrejmembto_check CHECK (ccrejmembto IN ('Nobody', 'Me', 'Specific')),
  CONSTRAINT mod_configs_ccfollmembto_check CHECK (ccfollmembto IN ('Nobody', 'Me', 'Specific')),
  PRIMARY KEY (id)
);

CREATE TABLE mod_stdmsgs (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  configid bigint,
  title varchar(255) NOT NULL,
  action text DEFAULT 'Reject' NOT NULL,
  subjpref varchar(255) NOT NULL,
  subjsuff varchar(255) NOT NULL,
  body text NOT NULL,
  rarelyused smallint DEFAULT 0 NOT NULL,
  autosend smallint DEFAULT 0 NOT NULL,
  newmodstatus text DEFAULT 'UNCHANGED' NOT NULL,
  newdelstatus text DEFAULT 'UNCHANGED' NOT NULL,
  edittext text DEFAULT 'Unchanged' NOT NULL,
  insert text DEFAULT 'Top',
  replybody text,
  CONSTRAINT mod_stdmsgs_action_check CHECK (action IN ('Approve', 'Reject', 'Leave', 'Approve Member', 'Reject Member', 'Leave Member', 'Leave Approved Message', 'Delete Approved Message', 'Leave Approved Member', 'Delete Approved Member', 'Edit', 'Hold Message', 'Edit and Message')),
  CONSTRAINT mod_stdmsgs_newmodstatus_check CHECK (newmodstatus IN ('UNCHANGED', 'MODERATED', 'DEFAULT', 'PROHIBITED', 'UNMODERATED')),
  CONSTRAINT mod_stdmsgs_newdelstatus_check CHECK (newdelstatus IN ('UNCHANGED', 'DIGEST', 'NONE', 'SINGLE', 'ANNOUNCEMENT')),
  CONSTRAINT mod_stdmsgs_edittext_check CHECK (edittext IN ('Unchanged', 'Correct Case')),
  CONSTRAINT mod_stdmsgs_insert_check CHECK (insert IN ('Top', 'Bottom')),
  PRIMARY KEY (id)
);

