  updated_at timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  PRIMARY KEY (id)
);

CREATE TABLE rippling_held_replies (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  chatid bigint NOT NULL,
  chatmsgid bigint NOT NULL,
  msgid bigint NOT NULL,
  replieruserid bigint NOT NULL,
  source text DEFAULT 'email' NOT NULL,
  lat double precision,
  lng double precision,
  status text DEFAULT 'held' NOT NULL,
  dueat timestamptz,
  created_at timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  releasedat timestamptz,
  CONSTRAINT rippling_held_replies_source_check CHECK (source IN ('email', 'tn', 'web')),
  CONSTRAINT rippling_held_replies_status_check CHECK (status IN ('held', 'released', 'dropped', 'taken-gone')),
  PRIMARY KEY (id)
);

