  direction text NOT NULL,
  severity text DEFAULT 'watch' NOT NULL,
  CONSTRAINT rippling_hotspots_direction_check CHECK (direction IN ('high', 'low')),
  CONSTRAINT rippling_hotspots_severity_check CHECK (severity IN ('watch', 'alert')),
  PRIMARY KEY (id)
);

