  sample_size integer DEFAULT 0 NOT NULL,
  created_at timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  CONSTRAINT rippling_live_metrics_period_type_check CHECK (period_type IN ('daily', 'weekly')),
  PRIMARY KEY (id)
);

