  PRIMARY KEY (msgid, groupid)
);

CREATE TABLE rippling_reach (
  msgid bigint NOT NULL,
  lat double precision NOT NULL,
  lng double precision NOT NULL,
  max_cumulative_users bigint,
  arrival timestamptz,
  mode varchar(8) DEFAULT 'drive' NOT NULL,
  tick integer DEFAULT 0 NOT NULL,
  min_tick integer,
  total_ticks integer DEFAULT 0 NOT NULL,
  total_freeglers bigint DEFAULT 0 NOT NULL,
  max_drive_min real,
  density_band varchar(8),
  density_radius_miles double precision,
  max_minutes_cap double precision,
  schedule text,
  reachable_group_ids jsonb,
  next_expansion_at timestamptz,
  status text DEFAULT 'expanding' NOT NULL,
  rejected_groups jsonb,
  created_at timestamptz,
  updated_at timestamptz,
  ripple_intro_sent smallint DEFAULT 0 NOT NULL,
  outer_bound geometry(Geometry,4326) NOT NULL,
  inner_bound geometry(Geometry,4326),
  polygon_cells bytea,
  max_polygon_cells bytea,
  overflow_cells jsonb,
  has_overflow smallint GENERATED ALWAYS AS (((overflow_cells is not null))::int) STORED,
  has_max_reach smallint GENERATED ALWAYS AS (((max_polygon_cells is not null))::int) STORED,
  reach_labels bytea,
  origin_union_secs real,
  reach_labels_next bytea,
  reach_labels_next_fp bigint,
