);

CREATE TABLE ux_experiment_exposures (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  experiment varchar(64) NOT NULL,
  arm varchar(16) NOT NULL,
  userid bigint NOT NULL,
  subject_type varchar(16) NOT NULL,
  subject_id bigint NOT NULL,
  stratum varchar(16),
  exposed_at timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  detail jsonb,
  PRIMARY KEY (id)
);

CREATE TABLE ux_experiment_reads (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  experiment_id bigint NOT NULL,
  read_at timestamptz NOT NULL,
  hours numeric(6,2) NOT NULL,
  metrics jsonb NOT NULL,
  summary text NOT NULL,
  PRIMARY KEY (id)
);

CREATE TABLE ux_experiments (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  flow varchar(32) NOT NULL,
  name varchar(64) NOT NULL,
  title varchar(160) NOT NULL,
  hypothesis text NOT NULL,
  change_description text NOT NULL,
  expected text NOT NULL,
  arms jsonb NOT NULL,
  status varchar(16) DEFAULT 'draft' NOT NULL,
  started_at timestamptz,
  ends_at timestamptz,
  decided_at timestamptz,
  decision text,
  result jsonb,
  pr_url varchar(255),
  cleanup_pr_url varchar(255),
  design jsonb,
  created_at timestamptz,
  updated_at timestamptz,
  PRIMARY KEY (id)
);

CREATE TABLE ux_feature_adoption_daily (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  date date NOT NULL,
  feature varchar(64) NOT NULL,
  active_users bigint DEFAULT 0 NOT NULL,
  using_users bigint DEFAULT 0 NOT NULL,
  sessions_using bigint DEFAULT 0 NOT NULL,
  PRIMARY KEY (id)
);

CREATE TABLE ux_field_daily (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  date date NOT NULL,
  flow varchar(32) NOT NULL,
  step varchar(64) NOT NULL,
  field varchar(64) NOT NULL,
  device_class varchar(16) DEFAULT '' NOT NULL,
  revisits bigint DEFAULT 0 NOT NULL,
  validation_failures bigint DEFAULT 0 NOT NULL,
  choice_switches bigint DEFAULT 0 NOT NULL,
  PRIMARY KEY (id)
);

CREATE TABLE ux_flow_daily (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  date date NOT NULL,
  flow varchar(32) NOT NULL,
  step varchar(64) NOT NULL,
  device_class varchar(16) DEFAULT '' NOT NULL,
  logged_in smallint DEFAULT 0 NOT NULL,
  is_app smallint DEFAULT 0 NOT NULL,
  variant varchar(64) DEFAULT '' NOT NULL,
  entered bigint DEFAULT 0 NOT NULL,
  reentered bigint DEFAULT 0 NOT NULL,
  completed bigint DEFAULT 0 NOT NULL,
  backed bigint DEFAULT 0 NOT NULL,
  abandoned bigint DEFAULT 0 NOT NULL,
  revisits bigint DEFAULT 0 NOT NULL,
  validation_failures bigint DEFAULT 0 NOT NULL,
  help_sought bigint DEFAULT 0 NOT NULL,
  dwell_p50_ms bigint,
  dwell_p90_ms bigint,
  PRIMARY KEY (id)
);

CREATE TABLE ux_flow_outcome_daily (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  date date NOT NULL,
  flow varchar(32) NOT NULL,
  device_class varchar(16) DEFAULT '' NOT NULL,
  logged_in smallint DEFAULT 0 NOT NULL,
  is_app smallint DEFAULT 0 NOT NULL,
  variant varchar(64) DEFAULT '' NOT NULL,
  started bigint DEFAULT 0 NOT NULL,
  submitted bigint DEFAULT 0 NOT NULL,
  submit_ok bigint DEFAULT 0 NOT NULL,
  submit_failed bigint DEFAULT 0 NOT NULL,
  completed bigint DEFAULT 0 NOT NULL,
  abandoned bigint DEFAULT 0 NOT NULL,
  resumed bigint DEFAULT 0 NOT NULL,
  total_dwell_p50_ms bigint,
  total_dwell_p90_ms bigint,
  PRIMARY KEY (id)
);

CREATE TABLE ux_flow_signal_daily (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  date date NOT NULL,
  flow varchar(32) NOT NULL,
  step varchar(64) NOT NULL,
  field varchar(64) DEFAULT '' NOT NULL,
  signal varchar(16) NOT NULL,
  device_class varchar(16) DEFAULT '' NOT NULL,
  logged_in smallint DEFAULT 0 NOT NULL,
  is_app smallint DEFAULT 0 NOT NULL,
  variant varchar(64) DEFAULT '' NOT NULL,
  people bigint DEFAULT 0 NOT NULL,
  finished bigint DEFAULT 0 NOT NULL,
  PRIMARY KEY (id)
);

CREATE TABLE ux_problems (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  flow varchar(32),
  kind varchar(16) DEFAULT 'problem' NOT NULL,
  group_name varchar(40),
  title varchar(160) NOT NULL,
  description text,
  prompt_id bigint,
  parent_id bigint,
  mentions bigint DEFAULT 0 NOT NULL,
  weight numeric(6,3),
  evidence jsonb,
  status varchar(16) DEFAULT 'open' NOT NULL,
  created_at timestamptz,
  updated_at timestamptz,
  PRIMARY KEY (id)
);

CREATE TABLE ux_prompt_responses (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  prompt_id bigint NOT NULL,
  userid bigint NOT NULL,
  answer jsonb NOT NULL,
  comment text,
  timestamp timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  PRIMARY KEY (id)
);

CREATE TABLE ux_prompts (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  kind varchar(16) NOT NULL,
  flow varchar(32),
  question varchar(255) NOT NULL,
  body text NOT NULL,
  options jsonb NOT NULL,
  images jsonb,
  status varchar(16) DEFAULT 'open' NOT NULL,
  max_responses bigint DEFAULT 200 NOT NULL,
  settings jsonb,
  created_at timestamptz,
  updated_at timestamptz,
  PRIMARY KEY (id)
);

CREATE TABLE ux_regret_daily (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  date date NOT NULL,
  signal varchar(32) NOT NULL,
  count bigint DEFAULT 0 NOT NULL,
  base bigint DEFAULT 0 NOT NULL,
  PRIMARY KEY (id)
);

CREATE TABLE ux_sample_sessions (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  date date NOT NULL,
  flow varchar(32) NOT NULL,
  step varchar(64) NOT NULL,
  signal varchar(32) NOT NULL,
  session_id varchar(64) NOT NULL,
  PRIMARY KEY (id)
);

CREATE TABLE ux_search_daily (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  date date NOT NULL,
  searches bigint DEFAULT 0 NOT NULL,
  zero_result bigint DEFAULT 0 NOT NULL,
  re_searched_60s bigint DEFAULT 0 NOT NULL,
  browse_sessions bigint DEFAULT 0 NOT NULL,
  browse_scrolled_out bigint DEFAULT 0 NOT NULL,
  PRIMARY KEY (id)
);

CREATE TABLE ux_telemetry_health_daily (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  date date NOT NULL,
  metric varchar(96) NOT NULL,
  expected numeric(14,2),
  observed numeric(14,2) DEFAULT 0.00 NOT NULL,
  ratio numeric(8,3),
  PRIMARY KEY (id)
);

CREATE TABLE visualise (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  msgid bigint NOT NULL,
  attid bigint NOT NULL,
  timestamp timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  fromuser bigint NOT NULL,
  touser bigint NOT NULL,
  fromlat numeric(10,6) NOT NULL,
  fromlng numeric(10,6) NOT NULL,
  tolat numeric(10,6) NOT NULL,
  tolng numeric(10,6) NOT NULL,
  distance integer NOT NULL,
  PRIMARY KEY (id)
);

CREATE TABLE volunteering (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  userid bigint,
  pending smallint DEFAULT 0 NOT NULL,
  title varchar(80) NOT NULL,
  online smallint DEFAULT 0 NOT NULL,
  location text NOT NULL,
  contactname varchar(80),
  contactphone varchar(80),
  contactemail varchar(80),
  contacturl varchar(255),
  description text,
  added timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  deleted smallint DEFAULT 0 NOT NULL,
  deletedby bigint,
  askedtorenew timestamptz,
  renewed timestamptz,
  expired smallint DEFAULT 0 NOT NULL,
  timecommitment text,
  heldby bigint,
  deletedcovid smallint DEFAULT 0 NOT NULL,
  externalid varchar(255),
  PRIMARY KEY (id)
);

CREATE TABLE volunteering_dates (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  volunteeringid bigint NOT NULL,
  start timestamptz,
  "end" timestamptz,
  applyby timestamptz,
  PRIMARY KEY (id)
);

CREATE TABLE volunteering_groups (
  volunteeringid bigint NOT NULL,
  groupid bigint NOT NULL,
  arrival timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE volunteering_images (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  opportunityid bigint,
  contenttype varchar(80) NOT NULL,
  archived smallint DEFAULT 0,
  data bytea,
  identification text,
  hash varchar(16),
  externaluid varchar(64),
  externalmods text,
  PRIMARY KEY (id)
);

CREATE TABLE vouchers (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  voucher citext NOT NULL,
  created timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  used timestamptz,
  groupid bigint,
  userid bigint,
  CONSTRAINT vouchers_voucher_length CHECK (char_length(voucher) <= 255),
  PRIMARY KEY (id)
);

CREATE TABLE weights (
  name varchar(80) NOT NULL,
  simplename varchar(80),
  weight numeric(5,2) NOT NULL,
  source text DEFAULT 'FRN 2009' NOT NULL,
  CONSTRAINT weights_source_check CHECK (source IN ('FRN 2009', 'Freegle')),
  PRIMARY KEY (name)
);

CREATE TABLE worrywords (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  keyword citext NOT NULL,
  substance varchar(255),
  type text NOT NULL,
  CONSTRAINT worrywords_keyword_length CHECK (char_length(keyword) <= 255),
  CONSTRAINT worrywords_type_check CHECK (type IN ('Regulated', 'Reportable', 'Medicine', 'Review', 'Allowed')),
  PRIMARY KEY (id)
);

