-- ON UPDATE CURRENT_TIMESTAMP columns
CREATE FUNCTION iznik_on_update_named() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  PERFORM set_config('iznik.named_' || TG_TABLE_NAME, coalesce(current_setting('iznik.named_' || TG_TABLE_NAME, true), '') || ',' || TG_ARGV[0] || ',', true);
  RETURN NULL;
END
$$;
CREATE FUNCTION iznik_on_update_done() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  PERFORM set_config('iznik.named_' || TG_TABLE_NAME, '', true);
  RETURN NULL;
END
$$;

CREATE FUNCTION iznik_on_update_abtest() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF ROW(NEW.id, NEW.uid, NEW.variant, NEW.shown, NEW.action, NEW.rate, NEW.suggest, NEW.timestamp) IS DISTINCT FROM ROW(OLD.id, OLD.uid, OLD.variant, OLD.shown, OLD.action, OLD.rate, OLD.suggest, OLD.timestamp) THEN
    IF NEW.timestamp IS NOT DISTINCT FROM OLD.timestamp AND position(',timestamp,' in coalesce(current_setting('iznik.named_abtest', true), '')) = 0 THEN NEW.timestamp := CURRENT_TIMESTAMP; END IF;
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER abtest_on_update BEFORE UPDATE ON abtest FOR EACH ROW EXECUTE FUNCTION iznik_on_update_abtest();
CREATE TRIGGER abtest_on_update_named_timestamp BEFORE UPDATE OF timestamp ON abtest FOR EACH STATEMENT EXECUTE FUNCTION iznik_on_update_named('timestamp');
CREATE TRIGGER abtest_on_update_done AFTER UPDATE ON abtest FOR EACH STATEMENT EXECUTE FUNCTION iznik_on_update_done();

CREATE FUNCTION iznik_on_update_charities() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF ROW(NEW.id, NEW.orgname, NEW.orgtype, NEW.charitynumber, NEW.orgdetails, NEW.website, NEW.social, NEW.description, NEW.contactemail, NEW.contactname, NEW.userid, NEW.status, NEW.geeknotified, NEW.created_at, NEW.updated_at) IS DISTINCT FROM ROW(OLD.id, OLD.orgname, OLD.orgtype, OLD.charitynumber, OLD.orgdetails, OLD.website, OLD.social, OLD.description, OLD.contactemail, OLD.contactname, OLD.userid, OLD.status, OLD.geeknotified, OLD.created_at, OLD.updated_at) THEN
    IF NEW.updated_at IS NOT DISTINCT FROM OLD.updated_at AND position(',updated_at,' in coalesce(current_setting('iznik.named_charities', true), '')) = 0 THEN NEW.updated_at := CURRENT_TIMESTAMP; END IF;
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER charities_on_update BEFORE UPDATE ON charities FOR EACH ROW EXECUTE FUNCTION iznik_on_update_charities();
CREATE TRIGGER charities_on_update_named_updated_at BEFORE UPDATE OF updated_at ON charities FOR EACH STATEMENT EXECUTE FUNCTION iznik_on_update_named('updated_at');
CREATE TRIGGER charities_on_update_done AFTER UPDATE ON charities FOR EACH STATEMENT EXECUTE FUNCTION iznik_on_update_done();

